test('renderInvoiceText ordering: VAT, Voucher, Total, Due, Paid', () => {
  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  invoice = applyVoucher(invoice, { code: 'TEST', amount: 1000 }).value;
  let issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, {
    amount: Math.floor(totals.total / 2),
    date: '2026-10-10',
  }).value;

  const text = renderInvoiceText(paid);
  const lines = text.split('\n');

  // Find indices of key lines
  const vatIndex = lines.findIndex(l => l.startsWith('VAT:'));
  const voucherIndex = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  const dueIndex = lines.findIndex(l => l.startsWith('Due:'));
  const paidIndex = lines.findIndex(l => l.startsWith('Paid:'));

  // Check ordering
  assert(vatIndex < voucherIndex);
  assert(voucherIndex < totalIndex);
  assert(totalIndex < dueIndex);
  assert(dueIndex < paidIndex);
});

