test('renderInvoiceText shows all enhancements together', () => {
  let invoice = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'STICKER', qty: 10 },
    ],
    terms: 'NET14',
  }).value;

  invoice = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  let issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, {
    amount: Math.floor(totals.total / 3),
    date: '2026-10-10',
  }).value;

  const text = renderInvoiceText(paid);
  // Check all enhancements are present
  assert.match(text, /INV-2026-0001/); // Invoice number
  assert.match(text, /Northwind Studio/); // Customer name
  assert.match(text, /discount:/); // Line discounts
  assert.match(text, /Voucher:/); // Voucher
  assert.match(text, /Total:/); // Total
  assert.match(text, /Due: 2026-10-21/); // Due date
  assert.match(text, /Paid:/); // Paid amount
});

